import { Group, Mesh, PlaneGeometry, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Color, DoubleSide } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Collection 1', typography: { fontSize: 39 } };
  const labelText = headlineItem.text ?? 'Collection 1';
  const fontSize = headlineItem.typography?.fontSize ?? 39;

  const root = new Group();
  root.name = 'collection-card-1-label';

  const content = new Group();
  root.add(content);

  const disposables = [];

  // ---- Engineered-gradient backdrop chip (ink -> surface, vertical) ----
  const CHIP_W = 1.9;
  const CHIP_H = 0.52;
  const chipGeo = new PlaneGeometry(CHIP_W, CHIP_H);
  const chipMat = new MeshPhysicalNodeMaterial({
    roughness: 0.55,
    metalness: 0.35,
    clearcoat: 0.15,
    clearcoatRoughness: 0.4,
    side: DoubleSide,
  });
  chipMat.colorNode = mix(color(palette.ink), color(palette.surface), uv().y);
  const chip = new Mesh(chipGeo, chipMat);
  chip.position.set(0, 0, 0);
  content.add(chip);
  disposables.push(chipGeo, chipMat);

  // ---- Accent underline (the single brightest element, <=10% of frame) ----
  const underlineGeo = new PlaneGeometry(CHIP_W * 0.9, 0.028);
  const underlineMat = new MeshStandardNodeMaterial({
    color: new Color(palette.accent),
    roughness: 0.4,
    metalness: 0.2,
  });
  underlineMat.emissive = new Color(palette.accent);
  underlineMat.emissiveIntensity = 1.1;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.set(0, -CHIP_H / 2 + 0.05, 0.005);
  content.add(underline);
  disposables.push(underlineGeo, underlineMat);

  // ---- Accent icon plane (atlas region 0,0,512,320 -> aspect 1.6) ----
  const ICON_H = 0.34;
  const ICON_W = ICON_H * (512 / 320);
  const iconGeo = new PlaneGeometry(ICON_W, ICON_H);
  const iconMat = new MeshBasicNodeMaterial({ transparent: true });
  const icon = new Mesh(iconGeo, iconMat);
  icon.position.set(-CHIP_W / 2 + ICON_W / 2 + 0.12, 0.01, 0.02);
  content.add(icon);
  disposables.push(iconGeo, iconMat);

  let iconTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        iconTexture = tex;
        iconMat.map = tex;
        iconMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // ---- Headline label text ----
  const label = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: palette.paper,
    align: 'left',
    maxWidthPx: 420,
  });
  label.position.set(-CHIP_W / 2 + ICON_W + 0.28, 0.02, 0.03);
  content.add(label);

  // ---- Motion: weighted-settle entrance on the inner content group only ----
  content.position.y = 0.22;
  content.scale.set(0.97, 0.97, 0.97);

  const tl = gsap.timeline();
  tl.to(content.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  });
  tl.to(
    content.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.4, ease: 'power2.out' },
    0,
  );
  tl.to(content.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.5,
    ease: 'power4.out',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    if (iconTexture && typeof iconTexture.dispose === 'function') {
      iconTexture.dispose();
    }
    if (typeof label.userData?.cleanup === 'function') {
      label.userData.cleanup();
    }
  };

  return root;
}
